package com.ias.finance;

import com.ias.trust.Chain;
import org.h2.jdbcx.JdbcDataSource;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mock.web.MockHttpServletRequest;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

class MoneyNotificationContextTest {
 @Test void exactMoneyFactCurrentAccountAndPermissionRevocation(){
  var ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1");var db=new JdbcTemplate(ds);db.execute("CREATE TABLE finance_money_terminal_fact(tenant_id BIGINT,operation_id CHAR(36),fault_group_id CHAR(36),customer_company_id BIGINT,actor_id BIGINT,account_version BIGINT,action_name VARCHAR(32),business_id CHAR(36),bill_id CHAR(36),completion_id CHAR(36),original_payment_id CHAR(36),amount_cents BIGINT,authority_digest CHAR(64),execution_receipts_digest CHAR(64),terminal_event_type VARCHAR(50),terminal_event_version VARCHAR(16),terminal_payload_json LONGTEXT,recorded_at TIMESTAMP,department_id BIGINT,applicant_user_id BIGINT)");db.execute("CREATE TABLE finance_outbox(tenant_id BIGINT,event_id CHAR(36),operation_id CHAR(36),event_type VARCHAR(50),payload_json LONGTEXT,recorded_at TIMESTAMP)");db.execute("CREATE TABLE finance_fee_group(tenant_id BIGINT,fault_group_id CHAR(36),customer_company_id BIGINT,row_version BIGINT)");db.execute("CREATE TABLE finance_money_account(tenant_id BIGINT,fault_group_id CHAR(36),row_version BIGINT)");
  String event=id(),group=id(),bill=id(),completion=id(),business=id(),authority="a".repeat(64),receipts="b".repeat(64),at=Instant.now().toString();var b=new LinkedHashMap<String,Object>();b.put("eventId",event);b.put("eventType","finance.collection_finalized");b.put("schemaVersion","1");b.put("tenantId","1");b.put("companyId","3");b.put("groupId",group);b.put("billId",bill);b.put("completionId",completion);b.put("accountVersion","2");b.put("action","COLLECTION_RECORDED");b.put("businessId",business);b.put("amountCents","100");b.put("authorityDigest",authority);b.put("executionReceiptsDigest",receipts);b.put("originalPaymentId",null);b.put("occurredAt",at);b.put("purpose","DELIVERY");var payload=new LinkedHashMap<>(b);payload.remove("eventId");payload.remove("eventType");payload.remove("purpose");
  db.update("INSERT INTO finance_money_terminal_fact VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP,?,?)",1L,event,group,3L,9L,2L,"COLLECTION_RECORDED",business,bill,completion,null,100L,authority,receipts,"FINANCE_COLLECTION_FINALIZED","1",Chain.JSON.writeValueAsString(payload),8L,9L);db.update("INSERT INTO finance_outbox VALUES(?,?,?,?,?,CURRENT_TIMESTAMP)",1L,event,event,"FINANCE_COLLECTION_FINALIZED","{}");db.update("INSERT INTO finance_fee_group VALUES(?,?,?,?)",1L,group,3L,4L);db.update("INSERT INTO finance_money_account VALUES(?,?,?)",1L,group,2L);
  var r=new MockHttpServletRequest();r.setSecure(true);r.setAttribute("ias.chain.edge","notification-finance");try(var chain=mockStatic(Chain.class,CALLS_REAL_METHODS)){chain.when(Chain::active).thenReturn(true);chain.when(Chain::role).thenReturn("finance");var c=new MoneyNotificationContextController(ds);assertEquals("8",c.context(b,r).get("departmentId"));var wrong=new LinkedHashMap<>(b);wrong.put("amountCents","101");assertEquals(409,assertThrows(com.ias.trust.Problem.class,()->c.context(wrong,r)).status);var read=new LinkedHashMap<>(b);read.put("purpose","READ");read.put("sessionToken","s");chain.when(()->Chain.call(eq("finance-identity"),eq("/internal/identity/domain-authorizations"),anyMap(),anyString(),anyLong())).thenReturn(Map.of("enabled",false,"tenantId","1","permissions",List.of("finance.money.read"),"companyIds",List.of("3"),"checkedAt",Instant.now().toString()));assertEquals(403,assertThrows(com.ias.trust.Problem.class,()->c.context(read,r)).status);db.update("UPDATE finance_money_account SET row_version=3");assertEquals("8",c.context(b,r).get("departmentId"));assertEquals(403,assertThrows(com.ias.trust.Problem.class,()->c.context(read,r)).status);db.update("UPDATE finance_money_account SET row_version=1");assertEquals(409,assertThrows(com.ias.trust.Problem.class,()->c.context(b,r)).status);}}
 static String id(){return UUID.randomUUID().toString();}
}
